    function pedestrianAt(x,z,r){for(const p of pedestrians)if(p.alive&&!p.dead&&Math.hypot(x-p.x,z-p.z)<r+.38)return p;return null;}
    function alertPedestrians(x,z,radius=56){const call=crimeWitnessCall,radius2=radius*radius;let reporter=null,reporterDistance2=radius2;for(const p of pedestrians){if(!p.alive||p.dead)continue;const dx=p.x-x,dz=p.z-z,distance2=dx*dx+dz*dz;if(distance2>radius2)continue;p.panic=Math.max(p.panic,3.2);const away=p.axis==='z'?Math.sign(p.z-z):Math.sign(p.x-x);if(away)p.dir=away;if(!p.officer&&!p.streetEventRole&&distance2<reporterDistance2){reporter=p;reporterDistance2=distance2;}}if(!call.pending&&call.cooldown<=0&&reporter){call.pending=true;call.reporter=reporter;call.timer=4.2+Math.random()*1.2;say('WITNESS SPOTTED YOU - '+Math.ceil(call.timer)+'s TO POLICE CALL');return true;}return false;}
