    function beginCrash(x,y,z,reason){if(crashTimer>0)return;surrendering=false;surrenderOfficer=null;surrenderElapsed=0;if(pierFishing.active)stopPierFishing(false);playerHealth=0;updateHealthHUD();crashFx.x=x;crashFx.y=y;crashFx.z=z;crashFx.time=1.6;crashTimer=1.6;if(driving&&vehicleType==='plane'){aircraft.x=x;aircraft.z=z;aircraft.groundY=surfaceHeightAt(x,z);aircraft.altitude=Math.max(0,y-aircraft.groundY);aircraft.speed=0;aircraft.verticalSpeed=0;aircraft.airborne=false;aircraft.health=0;aircraft.destroyed=true;aircraft.wreckTimer=18;addCombatEffect(x,y,z,1.55,3.1);}if(driving&&vehicleType==='bike'&&bikeRide){bikeRide.speed=bikeRide.vx=bikeRide.vz=0;bikeRide.roll=0;}audio.setHorn(false);if(document.pointerLockElement===canvas)document.exitPointerLock?.();say(reason+' · respawning');}
    function damagePlayer(amount){if(surrendering||crashTimer>0||damageCooldown>0)return;damageCooldown=.72;playerHealth=Math.max(0,playerHealth-amount);updateHealthHUD();if(playerHealth<=0){const vehicle=activeRoadRide(),plane=driving&&vehicleType==='plane',x=plane?aircraft.x:driving?vehicle.x:player.x,z=plane?aircraft.z:driving?vehicle.z:player.z,y=terrainHeightAt(x,z)+(plane?aircraft.altitude:1);beginCrash(x,y,z,'Wrecked');}}
