    function nearestHospitalFacility(x=player.x,z=player.z,range=18){let nearest=null,distance=range;for(const facility of civicFacilities){if(facility.type!=='hospital')continue;const d=Math.hypot(x-facility.x,z-facility.z);if(d<distance){nearest=facility;distance=d;}}return nearest;}function nearestSurrenderOfficer(x=player.x,z=player.z,range=24){let nearest=null,distance=range;for(const officer of pedestrians){const unit=officer.policeUnit;if(!officer.officer||!officer.alive||officer.dead||!unit||unit.destroyed||unit.stolen||!policeUnits.includes(unit))continue;const d=Math.hypot(x-officer.x,z-officer.z);if(d<distance){nearest=officer;distance=d;}}return nearest;}function nearestBookingStation(x=player.x,z=player.z){let nearest=null,distance=Infinity;for(const facility of civicFacilities){if(facility.type!=='police')continue;const d=Math.hypot(x-facility.x,z-facility.z);if(d<distance){nearest=facility;distance=d;}}return nearest;}function beginSurrender(){if(!started||finished||driving||inventoryOpen||garageOpen||mapOpen||crashTimer>0||pierFishing.active||gellhornMotel.inside||afterglowClub.inside||wantedLevel<=0||surrendering||!player.grounded)return false;const officer=nearestSurrenderOfficer();if(!officer)return false;officer.pause=0;surrendering=true;surrenderOfficer=officer;surrenderElapsed=0;selectedWeapon=0;updateWeaponHUD();keys.clear();fireHeld=false;player.jumpY=0;player.jumpV=0;player.grounded=true;const dx=officer.x-player.x,dz=officer.z-player.z;player.yaw=Math.atan2(-dx,-dz);say('HANDS UP · WAIT FOR VCPD');return true;}function completePoliceArrest(){if(!surrendering)return;const fine=Math.min(Math.max(0,cash),300+wantedLevel*275+Math.round(wantedHeat*4)),station=nearestBookingStation(),bookingX=station?.entryX??player.x,bookingZ=station?.entryZ??player.z,bookingYaw=station?.entryYaw??0,officer=surrenderOfficer,impounded=ride.stolenFromTraffic;surrendering=false;surrenderElapsed=0;surrenderOfficer=null;wantedHeat=0;crimeWitnessCall.pending=false;crimeWitnessCall.reporter=null;crimeWitnessCall.timer=0;cash=Math.max(0,cash-fine);if(officer){officer.aiming=false;officer.alive=false;}player.x=bookingX;player.z=bookingZ;player.yaw=bookingYaw;player.groundY=surfaceHeightAt(bookingX,bookingZ);player.jumpY=0;player.jumpV=0;player.grounded=true;cameraYaw=bookingYaw;walkBlend=0;keys.clear();fireHeld=false;playerHealth=100;damageCooldown=0;if(impounded){const personal=ride.hiddenPersonalRide||{};selectedCar=clamp(personal.selectedCar??0,0,vehicleCatalog.length-1);currentCar=tunedVehicle(selectedCar);ride.health=Math.min(currentCar.maxHealth,personal.health??currentCar.maxHealth);ride.destroyed=false;ride.wreckTimer=0;ride.x=bookingX+4.5;ride.z=bookingZ+3.5;ride.yaw=bookingYaw;ride.speed=ride.vx=ride.vz=ride.steerAngle=ride.wheelSpin=0;ride.pitch=ride.roll=0;ride.groundY=surfaceHeightAt(ride.x,ride.z);ride.stolenFromTraffic=false;ride.stolenPolice=false;delete ride.hiddenPersonalRide;}updateWantedHUD(0);syncCashDisplay();updateVehicleHUD();updateHealthHUD();updateWeaponHUD();say('VCPD BOOKING · -$'+fine.toLocaleString()+(impounded?' · CAR IMPOUNDED':' · RELEASED AT STATION'));}function hospitalTreatmentCost(){return Math.ceil(Math.ceil(100-playerHealth)*HOSPITAL_CARE_PER_HEALTH);}function grassriversHideoutCost(){const missing=Math.ceil(Math.max(0,100-playerHealth)),heat=wantedHeat>.01||wantedLevel>0;return 100+Math.ceil(missing*1.4)+(heat?180+Math.round(wantedLevel*210)+Math.round(wantedHeat*2):0);}
    function saveDryCurrentCheckpoint(){const data={version:1,safehouse:'dry-current',playerX:EVERGLADE_HIDEOUT.x+7,playerZ:EVERGLADE_HIDEOUT.z+6,playerYaw:0,rideX:ride.x,rideZ:ride.z,rideYaw:ride.yaw,rideHealth:ride.health,playerHealth,selectedCar,activeMission};try{localStorage.setItem(COAST_CHECKPOINT_KEY,JSON.stringify(data));const label=$('start').querySelector('span');if(label)label.textContent='Continue at Dry Current';return true;}catch{return false;}}
