    function interactGellhornMotel(){if(gellhornMotel.inside){if(Math.hypot(player.x-GELLHORN_MOTEL_ROOM.restX,player.z-GELLHORN_MOTEL_ROOM.restZ)<4.2){const cost=gellhornMotelRestCost();if(cash<cost){say('ROOM 06 needs $'+cost.toLocaleString()+' for a clean bed and a quiet night.');return true;}if(cost){cash-=cost;playerHealth=100;wantedHeat=0;updateHealthHUD();updateWantedHUD(0);syncCashDisplay();}say(saveGellhornMotelCheckpoint()?'GULFSTAR MOTOR COURT · ROOM 06 SAVED'+(cost?' · -$'+cost.toLocaleString():''):'ROOM 06 · CHECKPOINT STORAGE UNAVAILABLE.');return true;}gellhornMotel.inside=false;player.x=GELLHORN_MOTEL_ROOM.entryX;player.z=GELLHORN_MOTEL_ROOM.entryZ;player.yaw=0;player.groundY=surfaceHeightAt(player.x,player.z);player.jumpY=0;player.jumpV=0;player.grounded=true;cameraYaw=gellhornMotel.previousCameraYaw;cameraDistance=gellhornMotel.previousCameraDistance;say('PORT GELLHORN MOTOR COURT · ROOM 06 CHECKED OUT');return true;}if(Math.hypot(player.x-GELLHORN_MOTEL_ROOM.entryX,player.z-GELLHORN_MOTEL_ROOM.entryZ)>7)return false;gellhornMotel.previousCameraDistance=cameraDistance;gellhornMotel.previousCameraYaw=cameraYaw;gellhornMotel.inside=true;player.x=GELLHORN_MOTEL_ROOM.insideX;player.z=GELLHORN_MOTEL_ROOM.insideZ;player.yaw=0;player.groundY=surfaceHeightAt(player.x,player.z);player.jumpY=0;player.jumpV=0;player.grounded=true;cameraYaw=0;cameraDistance=Math.min(cameraDistance,6.2);say('GULFSTAR MOTOR COURT · ROOM 06');return true;}
    function updateGellhornMotelInterior(){if(!gellhornMotel.inside)return;const room=GELLHORN_MOTEL_ROOM;player.x=clamp(player.x,room.x-9.8,room.x+9.8);player.z=clamp(player.z,room.z-8.0,room.z+7.3);if(player.z>room.z+5.9)player.x=clamp(player.x,room.x-3.1,room.x+3.1);if(player.z>=room.z+7.3){gellhornMotel.inside=false;cameraYaw=gellhornMotel.previousCameraYaw;cameraDistance=gellhornMotel.previousCameraDistance;say('PORT GELLHORN MOTOR COURT · ROOM 06 CHECKED OUT');}}
    function afterglowDirectionForKey(key){return({w:'up',arrowup:'up',d:'right',arrowright:'right',s:'down',arrowdown:'down',a:'left',arrowleft:'left'})[key]||null;}
    function refreshAfterglowCard(){const card=$('afterglow-card'),state=afterglowClub.set;card.classList.toggle('show',afterglowClub.inside);card.classList.toggle('playing',state.active);card.classList.toggle('complete',!state.active&&state.summary.startsWith('SET LANDED'));card.classList.toggle('failed',!state.active&&state.summary.startsWith('SET MISSED'));$('afterglow-meter').setAttribute('aria-valuenow',String(state.score));$('afterglow-fill').style.width=(state.score/AFTERGLOW_SEQUENCE.length*100)+'%';if(state.active){const direction=AFTERGLOW_SEQUENCE[state.index]||'up',arrow={up:'UP',right:'RIGHT',down:'DOWN',left:'LEFT'}[direction];setTextIfChanged('afterglow-hint','BEAT '+(state.index+1)+' / '+AFTERGLOW_SEQUENCE.length+' - HIT '+arrow+' - STREAK '+state.streak+' - BEST '+state.best);}else setTextIfChanged('afterglow-hint',state.summaryTimer>0?state.summary:state.cooldown>0?'FLOOR SET READY IN '+Math.ceil(state.cooldown)+'S - BEST '+state.best+' / '+AFTERGLOW_SEQUENCE.length:'Press E near the floor to start an eight-beat set. WASD or arrow keys work. BEST '+state.best+' / '+AFTERGLOW_SEQUENCE.length);}
    function scheduleAfterglowCue(){const state=afterglowClub.set;if(!state.active||state.index>=AFTERGLOW_SEQUENCE.length)return;const delay=Math.max(0,state.beatAt-performance.now()*.001);audio.clubCue(AFTERGLOW_DIRECTIONS.indexOf(AFTERGLOW_SEQUENCE[state.index]),delay,false);}
    function startAfterglowSet(){const state=afterglowClub.set;if(!afterglowClub.inside||state.active)return;if(state.cooldown>0){say('THE FLOOR NEEDS '+Math.ceil(state.cooldown)+' SECONDS TO RESET.');return;}audio.start();keys.clear();fireHeld=false;state.active=true;state.index=0;state.score=0;state.streak=0;state.bestStreak=0;state.summary='';state.summaryTimer=0;state.beatAt=performance.now()*.001+.82;scheduleAfterglowCue();say('AFTERGLOW FLOOR SET - EIGHT BEATS');refreshAfterglowCard();}
