    function submitAfterglowBeat(direction){const state=afterglowClub.set;if(!state.active)return false;const offset=performance.now()*.001-state.beatAt;if(Math.abs(offset)>AFTERGLOW_HIT_WINDOW)return false;const correct=AFTERGLOW_SEQUENCE[state.index]===direction;if(correct){state.score++;state.streak++;state.bestStreak=Math.max(state.bestStreak,state.streak);audio.clubCue(AFTERGLOW_DIRECTIONS.indexOf(direction),0,true);}else{state.streak=0;audio.clubCue(0,0,false);}advanceAfterglowBeat();return true;}
    function finishAfterglowSet(cancelled){const state=afterglowClub.set;if(!state.active)return;state.active=false;keys.clear();if(cancelled){state.summary='SET MISSED - WALK BACK TO THE FLOOR TO TRY AGAIN.';state.summaryTimer=4;say('AFTERGLOW SET CUT SHORT');}else{const reward=state.score>=6?180+state.score*18:state.score*12;if(reward){cash+=reward;syncCashDisplay();}if(state.score>state.best){state.best=state.score;try{localStorage.setItem('neon-coast-afterglow-best',String(state.best));}catch{}}state.summary=state.score>=6?'SET LANDED - CROWD UP '+state.score+'/'+AFTERGLOW_SEQUENCE.length+' - +$'+reward:'SET MISSED - '+state.score+'/'+AFTERGLOW_SEQUENCE.length+' ON BEAT'+(reward?' - +$'+reward:'')+' - TRY AGAIN';state.summaryTimer=6;state.cooldown=18;say(state.score>=6?'AFTERGLOW SET LANDED - +$'+reward:'AFTERGLOW SET NEEDS ANOTHER PASS - '+state.score+'/'+AFTERGLOW_SEQUENCE.length);}refreshAfterglowCard();}
