    function updateAfterglowClub(dt){const club=afterglowClub,state=club.set;if(state.cooldown>0)state.cooldown=Math.max(0,state.cooldown-dt);if(!club.inside){$('afterglow-card').classList.remove('show','playing');return;}player.x=clamp(player.x,AFTERGLOW_CLUB.x-9.8,AFTERGLOW_CLUB.x+9.8);player.z=clamp(player.z,AFTERGLOW_CLUB.z-8.0,AFTERGLOW_CLUB.z+7.4);if(player.z>AFTERGLOW_CLUB.z+6.7)player.x=clamp(player.x,AFTERGLOW_CLUB.x-3.0,AFTERGLOW_CLUB.x+3.0);if(player.z>=AFTERGLOW_CLUB.z+7.4){exitAfterglowClub();return;}if(state.active){const now=performance.now()*.001;while(state.active&&now-state.beatAt>AFTERGLOW_HIT_WINDOW){state.streak=0;state.index++;if(state.index>=AFTERGLOW_SEQUENCE.length){finishAfterglowSet(false);break;}state.beatAt+=AFTERGLOW_BEAT_SECONDS;scheduleAfterglowCue();}}if(state.summaryTimer>0){state.summaryTimer=Math.max(0,state.summaryTimer-dt);if(state.summaryTimer===0)state.summary='';}refreshAfterglowCard();}
    function useGrassriversHideout(){const healed=Math.ceil(Math.max(0,100-playerHealth)),heat=wantedHeat>.01||wantedLevel>0;if(!healed&&!heat){say(saveDryCurrentCheckpoint()?'DRY CURRENT HIDEOUT · CHECKPOINT SAVED.':'CHECKPOINT STORAGE UNAVAILABLE.');return;}const cost=grassriversHideoutCost();if(cash<cost){say('The hideout crew needs $'+cost.toLocaleString()+' to patch you up and lose the tail.');return;}cash-=cost;playerHealth=100;if(heat)wantedHeat=0;updateHealthHUD();updateWantedHUD(0);syncCashDisplay();const saved=saveDryCurrentCheckpoint();say('DRY CURRENT HIDEOUT · +'+healed+' health'+(heat?' · police trail shaken':'')+' · -$'+cost.toLocaleString()+(saved?' · CHECKPOINT SAVED':' · SAVE FAILED'));}
